25	static int to_CUtensorMapDataType(DataType dtype) {
26	  CUtensorMapDataType tp;
27	  if (dtype.is_float()) {
28	    switch (dtype.bits()) {
29	    case 64:
30	      tp = CU_TENSOR_MAP_DATA_TYPE_FLOAT64;
31	      break;
32	    case 32:
33	      tp = CU_TENSOR_MAP_DATA_TYPE_FLOAT32;
34	      break;
35	    case 16:
36	      tp = CU_TENSOR_MAP_DATA_TYPE_FLOAT16;
37	      break;
38	    case 8:
39	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT8;
40	      break;
41	    default:
42	      ICHECK(0) << dtype;
43	    }
44	  } else if (dtype.is_bfloat16()) {
45	    tp = CU_TENSOR_MAP_DATA_TYPE_BFLOAT16;
46	  } else if (dtype.is_e4m3_float8() or dtype.is_e5m2_float8()) {
47	    tp = CU_TENSOR_MAP_DATA_TYPE_UINT8;
48	  } else if (dtype.is_int()) {
49	    switch (dtype.bits()) {
50	    case 64:
51	      tp = CU_TENSOR_MAP_DATA_TYPE_INT64;
52	      break;
53	    case 32:
54	      tp = CU_TENSOR_MAP_DATA_TYPE_INT32;
55	      break;
56	    case 16:
57	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT16;
58	      break;
59	    case 8:
60	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT8;
61	      break;
62	    default:
63	      ICHECK(0) << dtype;
64	    }
65	  } else if (dtype.is_uint()) {
66	    switch (dtype.bits()) {
67	    case 64:
68	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT64;
69	      break;
70	    case 32:
71	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT32;
72	      break;
73	    case 16:
74	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT16;
75	      break;
76	    case 8:
77	      tp = CU_TENSOR_MAP_DATA_TYPE_UINT8;
78	      break;
79	    default:
80	      ICHECK(0) << dtype;
81	    }
82	  } else {
83	    ICHECK(0) << dtype;
84	  }
85	  return static_cast<int>(tp);
86	}
87	
88	template <typename T> static Array<T> ReverseArray(Array<T> array) {
89	  return Array<T>{array.rbegin(), array.rend()};
90	}
91	
92	Stmt Copy::LowerBulkCopy(const LowerArgs &T, arith::Analyzer *analyzer) const {
93	  if (T.disable_tma_lower)
94	    return Stmt();
95	  if (!TargetIsHopper(T.target))
96	    return Stmt();
97	  bool is_load;
98	  if (src.scope() == "global" &&
99	      (dst.scope() == "shared.dyn" || dst.scope() == "shared")) {
100	    // Use the Hopper TMA bulk copy instructions
101	    is_load = true;
102	  } else if (dst.scope() == "global" &&
103	             (src.scope() == "shared.dyn" || src.scope() == "shared")) {
104	    is_load = false;
105	  } else {
106	    return Stmt();
107	  }
108	  Buffer global_tensor = is_load ? src : dst;
109	  Buffer shared_tensor = is_load ? dst : src;
110	  Array<Range> global_range = is_load ? src_range : dst_range;
111	  Array<Range> shared_range = is_load ? dst_range : src_range;
112	
113	  Array<PrimExpr> indices;
114	  for (auto r : shared_range)
115	    indices.push_back(r->min);
116	
117	  std::vector<PrimExpr> strides;
118	  PrimExpr stride = 1;
119	  for (size_t i = 0; i < shared_tensor->shape.size(); i++) {
120	    auto s = shared_tensor->shape[shared_tensor->shape.size() - i - 1];
121	    strides.insert(strides.begin(), stride);
122	    stride *= s;
123	  }
124	
125	  ICHECK(strides.size() == indices.size())
126	      << "strides.size() != indices.size()" << strides.size() << " "
127	      << indices.size();
128	  PrimExpr offset = 0;
129	  for (size_t i = 0; i < indices.size(); i++) {
130	    offset += indices[i] * strides[i];
131	  }
132	
133	  Layout shared_layout;
134	  if (T.layout_map.count(shared_tensor)) {
135	    shared_layout = T.layout_map[shared_tensor];
136	    shared_tensor = T.buffer_remap[shared_tensor];
137	  }
138	  if (T.layout_map.count(global_tensor)) {
139	    ICHECK(T.layout_map.count(global_tensor) == 0)
140	        << "Cannot support global layout.";
141	  }
142	
143	  TMADesc desc;
144	
145	  // Verify copy rank
146	  desc.rank = global_tensor->shape.size();
147	  ICHECK(desc.rank >= 1 && desc.rank <= 5) << desc.rank;
148	
149	  // Verify datatype
150	  ICHECK(global_tensor->dtype == shared_tensor->dtype)
151	      << "Copy between buffer " << global_tensor->name << " and "
152	      << shared_tensor->name << " with different data type "
153	      << global_tensor->dtype << " and " << shared_tensor->dtype;
154	
155	  desc.data_type = to_CUtensorMapDataType(global_tensor->dtype);
156	
157	  // Global Tensor Shape and Stride
158	  desc.global_addr = global_tensor->data;
159	  desc.global_shape = ReverseArray(global_tensor->shape);
160	  Array<PrimExpr> global_coords =
161	      ReverseArray(global_range.Map([](Range r) { return r->min; }));
162	  if (!global_tensor->strides.empty()) {
163	    desc.global_stride = ReverseArray(global_tensor->strides);
164	  } else {
165	    // Create stride from shape
166	    PrimExpr stride = 1;
167	    desc.global_stride.reserve(desc.rank);
168	    for (size_t i = 0; i < desc.rank; i++) {
169	      desc.global_stride.push_back(stride);
170	      stride *= desc.global_shape[i];
171	    }
172	  }
173	  // The first stride element should be 1
174	  ICHECK(is_one(desc.global_stride[0])) << desc.global_stride;
175	  // Make global stride in bytes
176	  desc.global_stride = desc.global_stride.Map(
177	      [&](PrimExpr e) { return e * global_tensor->dtype.bytes(); });
178	
179	  // Smem Box
180	  desc.smem_box =
181	      ReverseArray(global_range.Map([](Range r) { return r->extent; }));
182	  desc.smem_stride = Array<PrimExpr>(desc.rank, PrimExpr(1));
183	
184	  // L2 & OOB
185	  desc.l2_promotion = static_cast<int>(CU_TENSOR_MAP_L2_PROMOTION_L2_128B);
186	  desc.oob_fill = static_cast<int>(CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
187	
188	  // Detect smem layout
189	  desc.interleave = static_cast<int>(CU_TENSOR_MAP_INTERLEAVE_NONE);
190	  if (!shared_layout.defined()) {
191	    desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_NONE);
192	  } else {
193	    ICHECK(shared_layout->InputDim() == 2) << "Cannot detect TMA layout.";
194	    auto stride = as_const_int(shared_layout->InputShape()[0]);
195	    auto continuous = as_const_int(shared_layout->InputShape()[1]);
196	    ICHECK(stride != nullptr && continuous != nullptr);
197	    if (StructuralEqual()(shared_layout, makeGemmABLayoutPadded(
198	                                             *stride, *continuous,
199	                                             shared_tensor->dtype.bits()))) {
200	      desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_NONE);
201	    } else if (StructuralEqual()(
202	                   shared_layout,
203	                   makeHalfBankSwizzleLayout(*stride, *continuous,
204	                                             shared_tensor->dtype.bits()))) {
205	      desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_64B);
206	    } else if (StructuralEqual()(
207	                   shared_layout,
208	                   makeFullBankSwizzleLayout(*stride, *continuous,
209	                                             shared_tensor->dtype.bits()))) {
210	      desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_128B);
211	    } else {
212	      ICHECK(0) << "Cannot detect TMA layout.";
213	    }
214	  }
215	
216	  auto inner_box_dim = as_const_int(desc.smem_box[0]);
217	  ICHECK(inner_box_dim != nullptr);
218	  int instruction_dim = *inner_box_dim;
219	  if (desc.swizzle == static_cast<int>(CU_TENSOR_MAP_SWIZZLE_64B)) {
220	    instruction_dim = 64 / src->dtype.bytes();
221	  } else if (desc.swizzle == static_cast<int>(CU_TENSOR_MAP_SWIZZLE_128B)) {
222	    instruction_dim = 128 / src->dtype.bytes();
223	  }
224	  if (instruction_dim > 256) {
225	    // smem_box dim must be in [0, 256]
226	    // if is 512, we need to split the copy into two parts
227	    ICHECK((*inner_box_dim) % 256 == 0)
228	        << "inner_box_dim: " << *inner_box_dim << " is not divisible by 256";
229	    instruction_dim = 256;
230	  }
231	  ICHECK((*inner_box_dim) % instruction_dim == 0);
232	  desc.smem_box.Set(0, PrimExpr(instruction_dim));
233	
234	  Call create_descriptor =
235	      Call(DataType::Handle(), create_tma_descriptor(), desc.EncodeCallArgs());
236	
237	  Array<PrimExpr> args;
238	  args.reserve(desc.rank + 3);
239	  args.push_back(create_descriptor);
240	  if (is_load)
241	    args.push_back(0); // mbarrier id placeholder
242	  auto op = is_load ? tma_load() : tma_store();
243	
244	  Stmt tma_copy;
245	  PrimExpr total_elements = 1;
246	  for (auto e : desc.smem_box)
247	    total_elements *= e;
248	  if ((*inner_box_dim) != instruction_dim) {
249	    Var loop_var("i");
250	    int loop_extent = (*inner_box_dim) / instruction_dim;
251	
252	    PrimExpr shared_addr = shared_tensor.access_ptr(
253	        is_load ? 2 : 1, DataType::Handle(), 1,
254	        offset + total_elements * loop_var, total_elements);
255	    args.push_back(shared_addr);
256	    global_coords.Set(0, global_coords[0] + instruction_dim * loop_var);
257	    for (auto coord : global_coords)
258	      args.push_back(coord);
259	    tma_copy = For(loop_var, 0, loop_extent, ForKind::kUnrolled,
260	                   Evaluate(Call(DataType::Handle(), op, args)));
261	  } else {
262	    PrimExpr shared_addr = shared_tensor.access_ptr(
263	        is_load ? 2 : 1, DataType::Handle(), 1, offset, total_elements);
264	    args.push_back(shared_addr);
265	    for (auto coord : global_coords)
266	      args.push_back(coord);
267	    tma_copy = Evaluate(Call(DataType::Handle(), op, args));
268	  }
269	  tma_copy = IfThenElse(EQ(T.thread_var, T.thread_bounds->min), tma_copy);
270	
271	  return tma_copy;
272	}
273	
274	Array<PrimExpr> TMADesc::EncodeCallArgs() const {
275	  Array<PrimExpr> args;
276	  args.reserve(rank * 4 + 7);
277	
278	  args.push_back(data_type);
279	  args.push_back(static_cast<int>(rank));
280	  args.push_back(global_addr);
281	  for (auto e : global_shape)
282	    args.push_back(e);
283	  for (auto e : global_stride)
284	    args.push_back(e);
285	  for (auto e : smem_box)
286	    args.push_back(e);
287	  for (auto e : smem_stride)
288	    args.push_back(e);
289	  args.push_back(interleave);
290	  args.push_back(swizzle);
291	  args.push_back(l2_promotion);
292	  args.push_back(oob_fill);
293	
294	  return args;
295	}
296	
297	DataType cuTensorMapType() { return DataType::UInt(8, 128); }
298	
299	Conv2DIm2ColOp::Conv2DIm2ColOp(Array<PrimExpr> args, BufferMap vmap) {
300	  src = vmap[GetVarFromAccessPtr(args[0])];
301	  dst = vmap[GetVarFromAccessPtr(args[1])];
302	  nhw_step = args[2];
303	  c_step = args[3];
304	  kernel = args[4].as<IntImm>().value()->value;
305	  stride = args[5].as<IntImm>().value()->value;
306	  dilation = args[6].as<IntImm>().value()->value;
307	  padding = args[7].as<IntImm>().value()->value;
308	}
309	
310	Stmt Conv2DIm2ColOp::Lower(const LowerArgs &T,
311	                           arith::Analyzer *analyzer) const {
312	  ICHECK(TargetIsHopper(T.target));
313	  ICHECK(src.scope() == "global" &&
314	         (dst.scope() == "shared.dyn" || dst.scope() == "shared"));
315	  ICHECK(src->shape.size() == 4);
316	  ICHECK(dst->shape.size() == 2);
317	  ICHECK(src->dtype == dst->dtype);
318	  Layout shared_layout;
319	  if (T.layout_map.count(dst)) {
320	    shared_layout = T.layout_map[dst];
321	  }
322	
323	  TMAIm2ColDesc desc;
324	  desc.rank = src->shape.size();
325	  desc.data_type = to_CUtensorMapDataType(src->dtype);
326	  desc.global_addr = src->data;
327	  desc.global_shape = ReverseArray(src->shape);
328	  if (!src->strides.empty()) {
329	    desc.global_stride = ReverseArray(src->strides);
330	  } else {
331	    // Create stride from shape
332	    PrimExpr stride = 1;
333	    desc.global_stride.reserve(desc.rank);
334	    for (size_t i = 0; i < desc.rank; i++) {
335	      desc.global_stride.push_back(stride);
336	      stride *= desc.global_shape[i];
337	    }
338	  }
339	  // The first stride element should be 1
340	  ICHECK(is_one(desc.global_stride[0])) << desc.global_stride;
341	  // Make global stride in bytes
342	  desc.global_stride = desc.global_stride.Map(
343	      [&](PrimExpr e) { return e * src->dtype.bytes(); });
344	  desc.elem_stride = {1, stride, stride, 1};
345	  desc.lower_corner = {-padding, -padding};
346	  desc.upper_corner = {-padding, -padding};
347	  desc.smem_box_pixel = Downcast<IntImm>(dst->shape[0])->value;
348	  desc.smem_box_channel = Downcast<IntImm>(dst->shape[1])->value;
349	  desc.l2_promotion = static_cast<int>(CU_TENSOR_MAP_L2_PROMOTION_L2_128B);
350	  desc.oob_fill = static_cast<int>(CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
351	  desc.interleave = static_cast<int>(CU_TENSOR_MAP_INTERLEAVE_NONE);
352	  if (!shared_layout.defined()) {
353	    desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_NONE);
354	  } else {
355	    ICHECK(shared_layout->InputDim() == 2) << "Cannot detect TMA layout.";
356	    auto stride = as_const_int(shared_layout->InputShape()[0]);
357	    auto continuous = as_const_int(shared_layout->InputShape()[1]);
358	    ICHECK(stride != nullptr && continuous != nullptr);
359	    if (StructuralEqual()(shared_layout,
360	                          makeHalfBankSwizzleLayout(*stride, *continuous,
361	                                                    dst->dtype.bits()))) {
362	      desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_64B);
363	    } else if (StructuralEqual()(shared_layout, makeFullBankSwizzleLayout(
364	                                                    *stride, *continuous,
365	                                                    dst->dtype.bits()))) {
366	      desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_128B);
367	    } else {
368	      ICHECK(0) << "Cannot detect TMA layout.";
369	    }
370	  }
371	
372	  Call create_desc = Call(DataType::Handle(), create_tma_im2col_descriptor(),
373	                          desc.EncodeCallArgs());
374	
375	  Array<PrimExpr> global_coords; // c, w, h, n
376	  Array<PrimExpr> image_offset;  // w, h
377	  global_coords.reserve(desc.rank);
378	
379	  ICHECK(analyzer->CanProveEqual(
380	      FloorMod(desc.global_shape[0], desc.smem_box_channel), 0))
381	      << "Currently can only support divisible channel case";
382	
383	  global_coords.push_back(
384	      FloorMod(c_step * desc.smem_box_channel, desc.global_shape[0]));
385	  image_offset.push_back(
386	      dilation *
387	      FloorMod(FloorDiv(c_step * desc.smem_box_channel, desc.global_shape[0]),
388	               kernel));
389	  image_offset.push_back(dilation * FloorDiv(c_step * desc.smem_box_channel,
390	                                             desc.global_shape[0] * kernel));
391	
392	  PrimExpr h_dim =
393	      FloorDiv(src->shape[1] + 2 * padding - (kernel - 1) * dilation - 1,
394	               stride) +
395	      1;
396	  PrimExpr w_dim =
397	      FloorDiv(src->shape[2] + 2 * padding - (kernel - 1) * dilation - 1,
398	               stride) +
399	      1;
400	  global_coords.push_back(
401	      stride * FloorMod(nhw_step * desc.smem_box_pixel, w_dim) - padding);
402	  global_coords.push_back(
403	      stride *
404	          FloorMod(FloorDiv(nhw_step * desc.smem_box_pixel, w_dim), h_dim) -
405	      padding);
406	  global_coords.push_back(
407	      FloorDiv(nhw_step * desc.smem_box_pixel, w_dim * h_dim));
408	
409	  Array<PrimExpr> args;
410	  args.reserve(desc.rank * 2 + 1);
411	  args.push_back(create_desc);
412	  args.push_back(0); // mbar placeholder
413	  auto dst_buffer = T.buffer_remap.count(dst) ? T.buffer_remap[dst] : dst;
414	  auto shared_addr = dst_buffer.access_ptr(2);
415	  args.push_back(shared_addr);
416	  for (auto coord : global_coords)
417	    args.push_back(coord);
418	  for (auto offset : image_offset)
419	    args.push_back(offset);
420	
421	  Stmt tma_copy =
422	      IfThenElse(EQ(T.thread_var, T.thread_bounds->min),
423	                 Evaluate(Call(DataType::Handle(), tma_load_im2col(), args)));
424	  return tma_copy;
425	}
426	
427	Array<PrimExpr> TMAIm2ColDesc::EncodeCallArgs() const {
428	  Array<PrimExpr> args;
429	  args.reserve(rank * 5 + 5);
430	
431	  args.push_back(data_type);
432	  args.push_back(static_cast<int>(rank));
433	  args.push_back(global_addr);
434	  for (auto e : global_shape)
435	    args.push_back(e);
436	  for (auto e : global_stride)
437	    args.push_back(e);
438	  for (auto e : elem_stride)
439	    args.push_back(e);
440	  for (auto e : lower_corner)
441	    args.push_back(e);
442	  for (auto e : upper_corner)
443	    args.push_back(e);
444	  args.push_back(smem_box_pixel);
445	  args.push_back(smem_box_channel);
446	  args.push_back(interleave);
447	  args.push_back(swizzle);
448	  args.push_back(l2_promotion);
449	  args.push_back(oob_fill);
450	
451	  return args;
452	}
