231	    if (src.scope() == "global") {
232	      config.gm2ub = true;
233	      strideN = compute_strideN(src, src_extents);
234	      config.needs_strideN = true;
235	
236	      ss << "copy_gm_to_ub<";
237	      ss << get_dtype(src) << ", ";
238	      // The column dim is a COMPILE-TIME template arg. A runtime inner-extent
239	      // slice (dynamic width, e.g. a softmax's actual window tw_a < buffer
240	      // width) would put a non-const expr in the template -> invalid C++ ("use
241	      // of undeclared identifier"). Use the buffer's compile-time shape for the
242	      // template; the runtime width is already carried by the maskShapeN
243	      // function arg (validCol_dst). A const extent stays byte-identical (==
244	      // shape for a full copy, or the const slice width), so every existing
245	      // caller is unchanged -- only the previously-uncompilable runtime-slice
246	      // case changes.
247	      PrimExpr gm2ub_tmpl_n = dst_extents[dst->shape.size() - 1];
248	      if (!gm2ub_tmpl_n->IsInstance<IntImmNode>()) {
249	        gm2ub_tmpl_n = dst->shape[dst->shape.size() - 1];
250	        // The shape fallback must itself be a compile-time constant; a buffer
251	        // declared with a dynamic inner dim would still emit a non-const
252	        // template arg (the invalid-C++ case above), so fail early and clearly.
253	        ICHECK(gm2ub_tmpl_n->IsInstance<IntImmNode>())
254	            << "copy_gm_to_ub: the inner (column) dimension of the destination "
255	               "buffer shape must be a compile-time constant, but got "
256	            << gm2ub_tmpl_n;
257	      }
258	      ss << gm2ub_tmpl_n;
259	      if (dst->shape.size() > 1) {
260	        ss << ", " << compute_blocklen(dst, dst_extents);
261	      }
262	      ss << ">";
263	    } else if (dst.scope() == "global") {
264	      config.ub2gm = true;
265	      strideN = compute_strideN(dst, dst_extents);
266	      config.needs_strideN = true;
267	
268	      ss << "copy_ub_to_gm<";
269	      ss << get_dtype(dst) << ", ";
270	      // See copy_gm_to_ub above: a runtime inner-extent must use the buffer's
271	      // compile-time shape for the template col dim (runtime width is carried
272	      // by the maskShapeN function arg); const extents are byte-identical.
273	      PrimExpr ub2gm_tmpl_n = src_extents[src->shape.size() - 1];
274	      if (!ub2gm_tmpl_n->IsInstance<IntImmNode>()) {
275	        ub2gm_tmpl_n = src->shape[src->shape.size() - 1];
276	        // See copy_gm_to_ub: the shape fallback must itself be compile-time.
277	        ICHECK(ub2gm_tmpl_n->IsInstance<IntImmNode>())
278	            << "copy_ub_to_gm: the inner (column) dimension of the source "
279	               "buffer shape must be a compile-time constant, but got "
280	            << ub2gm_tmpl_n;
281	      }
282	      ss << ub2gm_tmpl_n;
283	      if (src->shape.size() > 1) {
284	        ss << ", " << compute_blocklen(src, src_extents);
285	      }
286	      ss << ">";
287	    } else if (dst.scope() == "shared.l1") {
288	      config.virtual_channel = true;
289	      ss << "copy_ub_to_l1<";
290	      ss << get_dtype(dst) << ", ";
291	      ss << src_extents[src->shape.size() - 1];
292	      if (src->shape.size() > 1) {
293	        ss << ", " << compute_blocklen(src, src_extents);
294	      }
295	      ss << ">";
296	    } else if (src.scope() == "wmma.accumulator") {
297	      config.virtual_channel = true;
298	      ss << "copy_l0c_to_ub<";
299	      ss << get_dtype(src) << ", " << get_dtype(dst) << ", ";
300	      ss << "layout::RowMajor, "; // In "ub -> gm -> l1" path, gm is
301	                                  // always row major
302	      ss << src->shape[src->shape.size() - 2] << ", "
303	         << src->shape[src->shape.size() - 1];
304	      ss << ", " << enRelu << ">";
305	    } else {
306	      PrimExpr len = 1;
307	      for (auto &shape : dst_extents) {
308	        len *= shape;
309	      }
310	      ss << "copy_ub_to_ub<" << get_dtype(dst) << ", " << get_dtype(src) << ", "
311	         << len << ">";
312	      config.ub2ub = true;
313	    }
314	  } else {
315	    LOG(FATAL) << "Unsupported scope: src = " << src.scope()
316	               << ", dst = " << dst.scope();
317	  }
318	
319	  if (!config.print_ub) {
320	    ss << "<" << get_dtype(src) << ", ";
321	
322	    if (config.l0c2gm) {
323	      ss << get_dtype(dst) << ", ";
324	    }
325	
326	    if (config.print_gm_layout) {
327	      ss << (T.layout_map.count(src) ? T.layout_map[src]->AscendLayoutStr()
328	                                     : "layout::RowMajor")
329	         << ", ";
330	    }
331	
332	    if (config.print_src_layout) {
333	      ICHECK(T.layout_map.count(src))
334	          << "Layout map does not contain source buffer: " << src->name;
335	      ss << T.layout_map[src]->AscendLayoutStr() << ", ";
336	    } else if (config.print_dst_layout) {
337	      ICHECK(T.layout_map.count(dst))
338	          << "Layout map does not contain destination buffer: " << dst->name;
339	      ss << T.layout_map[dst]->AscendLayoutStr() << ", ";
340	    }
341	
342	    int src_ndim = src->shape.size(), dst_ndim = dst->shape.size();
343	
344	    if (dst.scope() == "global") {
345	      ss << src->shape[src_ndim - 2] << ", " << src->shape[src_ndim - 1];
346	      if (config.l0c2gm) {
347	        ss << ", " << enRelu;
348	      }
349	      ss << ">";
350	    } else if (src.scope() == "global") {
351	      ss << dst->shape[dst_ndim - 2] << ", " << dst->shape[dst_ndim - 1] << ">";
352	    } else {
353	      ss << src->shape[src_ndim - 2] << ", " << src->shape[src_ndim - 1];
354	      if (config.l12l0) {
355	        transposeL1 == 0 ? ss << ", false" << ">" : ss << ", true" << ">";
356	      }
357	      // ss << src->shape[src_ndim - 2] << ", " << src->shape[src_ndim - 1] <<
358	      // ", "
359	      //    << dst->shape[dst_ndim - 2] << ", " << dst->shape[dst_ndim - 1] <<
360	      //    ">";
361	    }
