364	  auto src_indices = build_indices(src_range);
365	  auto dst_indices = build_indices(dst_range);
366	
367	  auto src_new_indices = T.layout_map.count(src)
368	                             ? T.layout_map[src]->Forward(src_indices)
369	                             : src_indices;
370	  auto dst_new_indices = T.layout_map.count(dst)
371	                             ? T.layout_map[dst]->Forward(dst_indices)
372	                             : dst_indices;
