374	  auto src_new_buffer = T.buffer_remap.count(src) ? T.buffer_remap[src] : src;
375	  auto dst_new_buffer = T.buffer_remap.count(dst) ? T.buffer_remap[dst] : dst;
376	
377	  PrimExpr src_len = 1;
378	  for (auto &shape : src_extents) {
379	    src_len *= shape;
