410	  auto compute_valid_extent = [](PrimExpr min_val, PrimExpr extent,
411	                                 PrimExpr shape) -> PrimExpr {
412	    PrimExpr remaining = shape - min_val;
413	    if (remaining.dtype().lanes() > 1) {
414	      return extent;
415	    }
416	    return Select(remaining >= extent, extent,
417	                  Select(remaining > 0, remaining, 0));
418	  };
419	
420	  auto find_active_dim_indices =
421	      [](const Array<PrimExpr> &extents) -> std::vector<int> {
422	    std::vector<int> active_indices;
423	    int size = static_cast<int>(extents.size());
424	
425	    // Traverse from 0 to size-1, find dimensions where extent != 1
426	    for (int i = 0; i < size; ++i) {
427	      if (auto *int_imm = extents[i].as<IntImmNode>()) {
428	        if (int_imm->value != 1) {
429	          active_indices.push_back(i);
430	        }
431	      } else {
432	        active_indices.push_back(i);
433	      }
434	    }
435	
436	    // The last dimension must always be included in the result
437	    if (size >= 1 &&
438	        (active_indices.empty() || active_indices.back() != size - 1)) {
439	      active_indices.push_back(size - 1);
440	    }
441	
442	    // Special: If extents.size() >= 2 and active_indices.size() == 1,
443	    // insert size-2 at the second-to-last position
444	    if (size >= 2 && active_indices.size() == 1) {
445	      active_indices.insert(active_indices.begin(), size - 2);
446	    }
447	
448	    return active_indices;
449	  };
450	
451	  PrimExpr validRow_src, validCol_src, validRow_dst, validCol_dst;
452	
453	  // src: compute validRow and validCol using active dimension indices
454	  std::vector<int> src_active = find_active_dim_indices(src_extents);
