464	  } else if (src_active.size() == 1) {
465	    int col_idx = src_active[0];
466	    validRow_src = Integer(1);
467	    validCol_src =
468	        compute_valid_extent(src_range[col_idx]->min,
469	                             src_range[col_idx]->extent, src->shape[col_idx]);
470	  } else {
471	    validRow_src = 0;
472	    validCol_src = 0;
473	  }
474	
475	  // dst: compute validRow and validCol using active dimension indices
476	  std::vector<int> dst_active = find_active_dim_indices(dst_extents);
477	  if (dst_active.size() >= 2) {
478	    int row_idx = dst_active[dst_active.size() - 2];
479	    int col_idx = dst_active.back();
480	    validRow_dst =
481	        compute_valid_extent(dst_range[row_idx]->min,
482	                             dst_range[row_idx]->extent, dst->shape[row_idx]);
483	    validCol_dst =
484	        compute_valid_extent(dst_range[col_idx]->min,
485	                             dst_range[col_idx]->extent, dst->shape[col_idx]);
486	  } else if (dst_active.size() == 1) {
487	    int col_idx = dst_active[0];
488	    validRow_dst = Integer(1);
489	    validCol_dst =
490	        compute_valid_extent(dst_range[col_idx]->min,
491	                             dst_range[col_idx]->extent, dst->shape[col_idx]);
492	  } else {
493	    validRow_dst = 0;
494	    validCol_dst = 0;
495	  }
496	
497	  Array<PrimExpr> new_args;
498	  new_args.push_back(StringImm(ss.str()));
499	  new_args.push_back(src_ptr);
500	  new_args.push_back(dst_ptr);
501	
502	  if (config.needs_strideN) {
503	    new_args.push_back(strideN);
504	  }
505	
506	  if (config.l0_dst_split) {
507	    int dst_dim = dst->shape.size();
508	    PrimExpr dm = dst->shape[dst_dim - 2];
509	    PrimExpr dn = dst->shape[dst_dim - 1];
510	    // realK overrides the L0 fractal's K extent so it matches the following
511	    // mma's runtime K. K is the trailing dim for matrix_a ([M, K]) and the
512	    // leading one for matrix_b ([K, N]). realK == 0 keeps dst->shape, which is
513	    // byte-identical for every existing L1->L0 copy.
514	    const auto *rk_imm = realK.as<IntImmNode>();
515	    if (!(rk_imm && rk_imm->value == 0)) {
516	      if (dst.scope() == "wmma.matrix_a") {
517	        dn = realK;
518	      } else if (dst.scope() == "wmma.matrix_b") {
519	        dm = realK;
520	      }
521	    }
522	    // realN overrides matrix_b's N extent, the axis realK does not cover.
523	    const auto *rn_imm = realN.as<IntImmNode>();
524	    if (!(rn_imm && rn_imm->value == 0) && dst.scope() == "wmma.matrix_b") {
525	      dn = realN;
526	    }
527	    new_args.push_back(dm);
528	    new_args.push_back(dn);
529	  }
530	
531	  if (config.l0c2gm) {
532	    new_args.push_back(compute_strideN(dst, dst_extents));
533	    new_args.push_back(validRow_dst);
534	    new_args.push_back(validCol_dst);
535	    new_args.push_back(src->shape[src->shape.size() - 2]);
536	    new_args.push_back(src->shape[src->shape.size() - 1]);
537	    new_args.push_back(Bool(enRelu)); // Add enable_relu parameter
538	    // unitFlag goes last, not in call order: this list is shared with the PTO
539	    // codegen, which reads several of these by position (the pad enum and the
540	    // relu flag among them). The ascendc codegen picks it up off the end and
541	    // emits it in the position the C++ helper expects.
542	    new_args.push_back(unitFlag);
543	  }
544	
545	  if (config.gm2l1) {
546	    new_args.push_back(compute_strideN(src, src_extents));
547	    new_args.push_back(validRow_src);
548	    new_args.push_back(validCol_src);
549	    new_args.push_back(dst->shape[dst->shape.size() - 2]);
550	    new_args.push_back(dst->shape[dst->shape.size() - 1]);
551	  }
552	
553	  if (config.gm2ub) {
554	    new_args.push_back(validRow_src);
555	    new_args.push_back(validCol_src);
556	    PrimExpr pad_val = padValue;
557	    if (pad_val->dtype != dst->dtype) {
558	      pad_val = Cast(dst->dtype, pad_val);
559	    }
560	    new_args.push_back(pad_val);
561	    // Physical UB tile dims (row pitch). These trail pad_val and are consumed
562	    // by AscendTailMaskPropagation to model the tail rect; CopyCodegen prints
563	    // only the first 4 extra args (strideN, validRow, validCol, pad_val).
564	    if (dst->shape.size() > 1) {
565	      new_args.push_back(dst->shape[dst->shape.size() - 2]);
566	    }
567	    new_args.push_back(dst->shape[dst->shape.size() - 1]);
568	  }
569	
570	  if (config.ub2gm) {
571	    new_args.push_back(validRow_dst);
572	    new_args.push_back(validCol_dst);
573	    if (src->shape.size() > 1) {
574	      new_args.push_back(src->shape[src->shape.size() - 2]);
575	    }
576	    new_args.push_back(src->shape[src->shape.size() - 1]);
577	  }
578	
579	  if (config.virtual_channel) {
580	    new_args.push_back(src_extents[src_extents.size() - 1]); // src_N
581	    if (src_extents.size() >= 2) {
582	      new_args.push_back(src_extents[src_extents.size() - 2]); // src_M
583	    } else {
584	      new_args.push_back(IntImm(DataType::Int(32), 0)); // 1D: no M dim
585	    }
586	    new_args.push_back(dst_extents[dst_extents.size() - 2]); // dst_M
587	    new_args.push_back(dst_extents[dst_extents.size() - 1]); // dst_N
588	    // Add tmp buffer for UB->L1 copy on A5 (for ND->Nz conversion)
589	    if (tmp.defined()) {
590	      new_args.push_back(tmp_ptr);
591	      new_args.push_back(tmp_extents[tmp_extents.size() - 2]); // tmp_M
592	      new_args.push_back(tmp_extents[tmp_extents.size() - 1]); // tmp_N
593	    }
594	  }
595	
596	  if (config.ub2ub) {
597	    PrimExpr src_tile_rows = src_extents.size() >= 2
598	                                 ? src_extents[src_extents.size() - 2]
599	                                 : Integer(1);
600	    PrimExpr src_tile_cols = src_extents[src_extents.size() - 1];
601	    PrimExpr src_buf_cols = src->shape[src->shape.size() - 1];
602	    PrimExpr dst_tile_rows = dst_extents.size() >= 2
603	                                 ? dst_extents[dst_extents.size() - 2]
604	                                 : Integer(1);
605	    PrimExpr dst_tile_cols = dst_extents[dst_extents.size() - 1];
606	    PrimExpr dst_buf_cols = dst->shape[dst->shape.size() - 1];
607	    new_args.push_back(src_tile_rows);
608	    new_args.push_back(src_tile_cols);
609	    new_args.push_back(src_buf_cols);
610	    new_args.push_back(dst_tile_rows);
611	    new_args.push_back(dst_tile_cols);
612	    new_args.push_back(dst_buf_cols);
613	  }
614	  // if (config.l12l0) {
615	  //   ICHECK(src->shape.size() == dst->shape.size());
616	  //   bool is_extract = false;
617	  //   auto dst_shape_size = dst->shape.size();
618	  //   auto src_shape_size = src->shape.size();
619	  //   for (int i = dst_shape_size - 1; i >= dst_shape_size - 2; i--) {
620	  //     if (i == -1) {
621	  //         break;
622	  //     }
623	  //     // std::cout << "dst_shape_size -2 = " << dst_shape_size - 2  << ", i =
624	  //     " << i << ", dst->shape: " << dst->shape[i]
625	  //     //   << "src->shape: " << src->shape[i] << "\n";
626	  //     if (src->shape[i].as<IntImmNode>()->value !=
627	  //     dst->shape[i].as<IntImmNode>()->value) {
628	  //         is_extract = true;
629	  //     }
630	  //     new_args.push_back(src_indices[i]);
631	  //   }
632	  //   new_args.push_back(Bool(is_extract));
633	  //   auto dst_var = dst_ptr.as<CallNode>()->args[1];
634	  //   std::cout << "newargs in copy to l1: " << new_args << "\n";
