642	Stmt AscendAtomicAdd::Lower(const LowerArgs &T,
643	                            arith::Analyzer *analyzer) const {
644	  auto get_dtype = [](const Buffer &buf) -> std::string {
645	    auto dtype = buf->dtype;
646	    if (dtype.is_float16()) {
647	      return "half";
648	    } else if (dtype.is_float() && dtype.bits() == 32) {
649	      return "float";
650	    } else if (dtype.is_int() && dtype.bits() == 8) {
651	      return "int8_t";
652	    } else if (dtype.is_int() && dtype.bits() == 16) {
653	      return "int16_t";
654	    } else if (dtype.is_int() && dtype.bits() == 32) {
655	      return "int";
656	    } else if (dtype.is_int() && dtype.bits() == 64) {
657	      return "int64_t";
658	    } else if (dtype.is_uint() && dtype.bits() == 8) {
659	      return "uint8_t";
660	    } else if (dtype.is_uint() && dtype.bits() == 16) {
661	      return "uint16_t";
662	    } else if (dtype.is_uint() && dtype.bits() == 32) {
663	      return "uint32_t";
664	    } else if (dtype.is_uint() && dtype.bits() == 64) {
665	      return "uint64_t";
666	    } else if (dtype.is_bfloat16()) {
667	      return "bfloat16_t";
668	    } else if (dtype.is_float8_e4m3fn()) {
669	      return "float8_e4m3_t";
670	    } else if (dtype.is_float8_e5m2()) {
671	      return "float8_e5m2_t";
672	    }
673	    LOG(FATAL) << "Unsupported data type for tl.ascend_atomic_add: " << dtype;
674	    return "";
675	  };
676	
677	  auto compute_strideN = [](const Buffer &buf,
678	                            const Array<PrimExpr> &extents) -> PrimExpr {
679	    PrimExpr strideN = buf->shape[buf->shape.size() - 1];
680	    if (extents.size() > 1) {
681	      for (int i = extents.size() - 2; i >= 0; --i) {
682	        auto *extent = extents[i].as<IntImmNode>();
683	        if (!extent || extent->value != 1) {
684	          break;
685	        }
686	        strideN = strideN * buf->shape[i];
687	      }
688	    }
689	    return strideN;
690	  };
691	
692	  auto compute_blocklen = [](const Buffer &buf,
693	                             const Array<PrimExpr> &extents) -> PrimExpr {
694	    PrimExpr res = buf->shape[buf->shape.size() - 2];
695	    auto ext_size = extents.size();
696	    if (ext_size > 1 && extents[ext_size - 2]->IsInstance<IntImmNode>() &&
697	        res->IsInstance<IntImmNode>()) {
698	      auto extent =
699	          static_cast<int>(extents[ext_size - 2].as<IntImmNode>()->value);
700	      auto shape = static_cast<int>(res.as<IntImmNode>()->value);
701	      res = shape < extent ? res : extents[ext_size - 2];
702	    }
703	    return res;
704	  };
705	
706	  auto build_indices = [](const Array<Range> &range) -> Array<PrimExpr> {
707	    Array<PrimExpr> indices;
708	    for (size_t i = 0; i < range.size(); i++) {
709	      indices.push_back(range[i]->min);
710	    }
711	    return indices;
712	  };
713	
714	  auto compute_valid_extent = [](PrimExpr min_val, PrimExpr extent,
715	                                 PrimExpr shape) -> PrimExpr {
716	    PrimExpr remaining = shape - min_val;
717	    if (remaining.dtype().lanes() > 1) {
718	      return extent;
719	    }
720	    return Select(remaining >= extent, extent,
721	                  Select(remaining > 0, remaining, 0));
722	  };
723	
724	  auto find_active_dim_indices =
725	      [](const Array<PrimExpr> &extents) -> std::vector<int> {
726	    std::vector<int> active_indices;
727	    int size = static_cast<int>(extents.size());
728	    for (int i = 0; i < size; ++i) {
729	      if (auto *int_imm = extents[i].as<IntImmNode>()) {
730	        if (int_imm->value != 1) {
731	          active_indices.push_back(i);
732	        }
733	      } else {
734	        active_indices.push_back(i);
735	      }
736	    }
737	    if (size >= 1 &&
738	        (active_indices.empty() || active_indices.back() != size - 1)) {
739	      active_indices.push_back(size - 1);
740	    }
741	    if (size >= 2 && active_indices.size() == 1) {
742	      active_indices.insert(active_indices.begin(), size - 2);
743	    }
744	    return active_indices;
745	  };
746	
747	  ICHECK(dst.scope() == "global")
748	      << "tl.ascend_atomic_add V1 requires global dst, got " << dst.scope();
749	  ICHECK(src.scope() == "shared.ub" || src.scope() == "wmma.accumulator")
750	      << "tl.ascend_atomic_add V1 requires UB/shared or L0C/wmma.accumulator "
751	         "src, got "
752	      << src.scope();
753	  ICHECK(src->dtype == dst->dtype)
754	      << "tl.ascend_atomic_add requires src and dst dtype to match, got src "
755	      << src->dtype << " and dst " << dst->dtype;
756	  ICHECK_EQ(src_extents.size(), src->shape.size())
757	      << "tl.ascend_atomic_add source region rank must match source buffer "
758	         "rank";
759	  ICHECK_EQ(dst_extents.size(), dst->shape.size())
760	      << "tl.ascend_atomic_add destination region rank must match "
761	         "destination buffer rank";
762	
763	  std::stringstream ss;
764	  // Same compile-time-template-arg fix as the GM<->UB copy above (see
765	  // AscendCopy::Lower): the inner (column) dim is a template arg, so a runtime
766	  // inner-extent -- e.g. atomic_add(A[rows, 0:n], src_ub[:, 0:n]) with a
767	  // dynamic n -- would put a non-const expr in the template and emit invalid
768	  // C++. Use the source buffer's compile-time shape for the template; the
769	  // runtime column count is carried by validCol_dst below, so the DMA still
770	  // adds exactly the runtime number of columns. A const extent stays
771	  // byte-identical, so every existing caller is unchanged.
772	  PrimExpr atomic_tmpl_n = src_extents[src->shape.size() - 1];
773	  if (!atomic_tmpl_n->IsInstance<IntImmNode>()) {
774	    atomic_tmpl_n = src->shape[src->shape.size() - 1];
775	    ICHECK(atomic_tmpl_n->IsInstance<IntImmNode>())
776	        << "tl.ascend_atomic_add: the inner (column) dimension of the source "
777	           "buffer shape must be a compile-time constant, but got "
778	        << atomic_tmpl_n;
779	  }
780	  if (src.scope() == "shared.ub") {
781	    ss << "tl::ascend::atomic_add_ub_to_gm<";
782	    ss << get_dtype(dst) << ", " << atomic_tmpl_n;
783	    if (src->shape.size() > 1) {
784	      ss << ", " << compute_blocklen(src, src_extents);
785	    }
786	    ss << ">";
787	  } else if (src.scope() == "wmma.accumulator") {
788	    ss << "tl::ascend::atomic_add_l0c_to_gm<";
789	    ss << get_dtype(src) << ", " << get_dtype(dst) << ", "
790	       << (T.layout_map.count(src) ? T.layout_map[src]->AscendLayoutStr()
791	                                   : "layout::RowMajor");
792	    if (src->shape.size() > 1) {
793	      ss << ", " << compute_blocklen(src, src_extents) << ", " << atomic_tmpl_n;
794	    } else {
795	      ss << ", 1, " << atomic_tmpl_n;
796	    }
797	    ss << ">";
798	  }
799	
800	  auto src_indices = build_indices(src_range);
801	  auto dst_indices = build_indices(dst_range);
802	  auto src_new_indices = T.layout_map.count(src)
803	                             ? T.layout_map[src]->Forward(src_indices)
804	                             : src_indices;
805	  auto dst_new_indices = T.layout_map.count(dst)
806	                             ? T.layout_map[dst]->Forward(dst_indices)
807	                             : dst_indices;
808	
809	  auto src_new_buffer = T.buffer_remap.count(src) ? T.buffer_remap[src] : src;
810	  auto dst_new_buffer = T.buffer_remap.count(dst) ? T.buffer_remap[dst] : dst;
811	
812	  // Scalarize indices: extract base from Ramp expressions to avoid vector lane
813	  // mismatches when Ramp lanes differ across dimensions (e.g. int32x32 vs
814	  // int32x64). The Ramp lanes already contribute to the access extent (src_len
815	  // / dst_len).
816	  auto scalarize = [](const PrimExpr &idx) -> PrimExpr {
817	    if (const auto *ramp = idx.as<RampNode>()) {
818	      return ramp->base;
819	    }
820	    return idx;
821	  };
822	  auto src_scalar_indices = src_new_indices.Map(scalarize);
823	  auto dst_scalar_indices = dst_new_indices.Map(scalarize);
824	
825	  PrimExpr src_len = 1;
826	  for (auto &shape : src_extents) {
827	    src_len *= shape;
828	  }
829	  // dst_len must also account for lanes in Ramp indices
830	  PrimExpr dst_len = 1;
831	  for (size_t i = 0; i < dst_extents.size(); ++i) {
832	    PrimExpr dim_len = dst_extents[i];
833	    if (const auto *ramp = dst_new_indices[i].as<RampNode>()) {
834	      dim_len = dim_len * ramp->lanes;
835	    }
836	    dst_len = dst_len * dim_len;
837	  }
838	
839	  auto src_offset = src_new_buffer.OffsetOf(src_scalar_indices).back();
840	  auto dst_offset = dst_new_buffer.OffsetOf(dst_scalar_indices).back();
841	
842	  auto src_ptr = src_new_buffer.access_ptr(1, src_new_buffer->dtype, 1,
843	                                           src_offset, src_len);
844	  auto dst_ptr = dst_new_buffer.access_ptr(2, dst_new_buffer->dtype, 1,
845	                                           dst_offset, dst_len);
846	
847	  // Compute effective extents accounting for lanes in Ramp indices,
848	  // so that find_active_dim_indices correctly identifies the 2D access pattern.
849	  Array<PrimExpr> effective_dst_extents;
850	  for (size_t i = 0; i < dst_extents.size(); ++i) {
851	    PrimExpr eff = dst_extents[i];
852	    if (const auto *ramp = dst_new_indices[i].as<RampNode>()) {
853	      // When a dimension was vectorized from extent N to 1 vector with N lanes,
854	      // the true element count is the Ramp lanes.  When the extent already
855	      // reflects the total element count (extent == Ramp lanes), keep it as-is.
856	      if (is_one(dst_extents[i])) {
857	        eff = ramp->lanes;
858	      }
859	    }
860	    effective_dst_extents.push_back(eff);
861	  }
862	
863	  // Identify row/col Ramp dimensions for stride and boundary computation.
864	  // When vectorized, Ramps with different lane counts (e.g. 32, 64) mark the
865	  // true 2D access pattern, bypassing scrambled extents.
866	  auto get_ramp_lanes = [](const PrimExpr &idx) -> int {
867	    if (const auto *ramp = idx.as<RampNode>()) {
868	      if (auto *imm = ramp->lanes.as<IntImmNode>()) {
869	        return static_cast<int>(imm->value);
870	      }
871	    }
872	    return 0;
873	  };
874	  int row_ramp_idx = -1, col_ramp_idx = -1;
875	  for (size_t i = 0; i < dst_new_indices.size(); ++i) {
876	    int lanes = get_ramp_lanes(dst_new_indices[i]);
877	    if (lanes > 1) {
878	      if (row_ramp_idx < 0 ||
879	          lanes < get_ramp_lanes(dst_new_indices[row_ramp_idx])) {
880	        col_ramp_idx = row_ramp_idx >= 0 ? row_ramp_idx : col_ramp_idx;
881	        row_ramp_idx = static_cast<int>(i);
882	      } else {
883	        col_ramp_idx = static_cast<int>(i);
884	      }
885	    }
886	  }
887	
888	  PrimExpr validRow_dst, validCol_dst;
889	  if (row_ramp_idx >= 0 && col_ramp_idx >= 0) {
890	    // Use Ramp-identified dimensions for boundary checks
891	    PrimExpr row_min = dst_scalar_indices[row_ramp_idx];
892	    PrimExpr col_min = dst_scalar_indices[col_ramp_idx];
893	    PrimExpr row_extent = effective_dst_extents[row_ramp_idx];
894	    PrimExpr col_extent = effective_dst_extents[col_ramp_idx];
895	    validRow_dst =
896	        compute_valid_extent(row_min, row_extent, dst->shape[row_ramp_idx]);
897	    validCol_dst =
898	        compute_valid_extent(col_min, col_extent, dst->shape[col_ramp_idx]);
899	  } else {
900	    std::vector<int> dst_active =
901	        find_active_dim_indices(effective_dst_extents);
902	    if (dst_active.size() >= 2) {
903	      int row_idx = dst_active[dst_active.size() - 2];
904	      int col_idx = dst_active.back();
905	      PrimExpr row_min = dst_scalar_indices[row_idx];
906	      PrimExpr col_min = dst_scalar_indices[col_idx];
907	      PrimExpr row_extent = effective_dst_extents[row_idx];
908	      PrimExpr col_extent = effective_dst_extents[col_idx];
909	      validRow_dst =
910	          compute_valid_extent(row_min, row_extent, dst->shape[row_idx]);
911	      validCol_dst =
912	          compute_valid_extent(col_min, col_extent, dst->shape[col_idx]);
913	    } else if (dst_active.size() == 1) {
914	      int col_idx = dst_active[0];
915	      PrimExpr col_min = dst_scalar_indices[col_idx];
916	      PrimExpr col_extent = effective_dst_extents[col_idx];
917	      validRow_dst = Integer(1);
918	      validCol_dst =
919	          compute_valid_extent(col_min, col_extent, dst->shape[col_idx]);
920	    } else {
921	      validRow_dst = Integer(0);
922	      validCol_dst = Integer(0);
923	    }
924	  }
925	
926	  // Compute strideN: when Ramp dimensions are identified, use buffer shape
927	  // to compute the inter-row stride. Otherwise fall back to extent-based logic.
928	  PrimExpr strideN;
929	  if (row_ramp_idx >= 0 && col_ramp_idx >= 0) {
930	    strideN = Integer(1);
931	    for (int i = row_ramp_idx + 1; i < static_cast<int>(dst->shape.size());
932	         ++i) {
933	      strideN = strideN * dst->shape[i];
934	    }
935	  } else {
936	    strideN = compute_strideN(dst, dst_extents);
937	  }
938	
939	  Array<PrimExpr> new_args;
940	  new_args.push_back(StringImm(ss.str()));
941	  new_args.push_back(src_ptr);
942	  new_args.push_back(dst_ptr);
943	  new_args.push_back(strideN);
944	  new_args.push_back(validRow_dst);
945	  new_args.push_back(validCol_dst);
946	
947	  auto new_call = Call(DataType::Handle(), builtin::call_extern(), new_args);
948	  return Evaluate(new_call);
949	}
