template <typename T, uint32_t dstM, uint32_t dstN>
CATLASS_DEVICE void
copy_gm_to_l1(LocalTensor<T> dstTensor, GlobalTensor<T> srcTensor,
              uint32_t realSrcN = 1, uint32_t realTailM = 0,
              uint32_t realTailN = 0, bool need_clear = true) {
  uint32_t tailM = realTailM == 0 ? dstM : realTailM;
  uint32_t tailN = realTailN == 0 ? dstN : realTailN;
  // Only the primary copy (dst offset 0, i.e. need_clear == true) is allowed to
  // zero-init the full L1 tile. Sub-region copies (need_clear == false, e.g.
  // the second DMA of a splice / vertical-merge pattern) must NOT clear,
  // otherwise they clobber data already written into the same NZ tile. The
  // full-tile clear is only correct when it targets the tile base, which the
  // codegen guarantees by passing need_clear = (dst_offset == 0).
  if (need_clear && (tailM != dstM || tailN != dstN)) {
    AscendC::InitConstValue(
        dstTensor,
        {1, static_cast<uint16_t>(dstM * dstN * sizeof(T) / 32), 0, 0});
    AscendC::PipeBarrier<PIPE_MTE2>();
  }
  auto layout = MakeLayoutFromTag(LayoutGM{tailM, realSrcN});
  auto src_LAYOUT = MakeLayoutTile(layout, tla::MakeShape(tailM, tailN));
  auto src = tla::MakeTensor<decltype(srcTensor), decltype(src_LAYOUT),
                             AscendC::TPosition::GM>(srcTensor, src_LAYOUT);

  using LayoutL1_ = Catlass::detail::TagToLayout_t<T, LayoutL1>;
  constexpr auto layoutInL1 = tla::MakeLayout<T, LayoutL1_>(dstM, dstN);
  auto dst = tla::MakeTensor<decltype(dstTensor), decltype(layoutInL1),
                             AscendC::TPosition::A1>(dstTensor, layoutInL1);

  TileCopyTla<ArchTag, decltype(src), decltype(dst)> tileCopier;
  tileCopier(dst, src);
}

template <typename T, uint32_t srcM, uint32_t srcN, bool transpose = false>
CATLASS_DEVICE void copy_l1_to_l0a(LocalTensor<T> dstTensor,
                                   LocalTensor<T> srcTensor, uint32_t dstM,
                                   uint32_t dstN) {
  using LayoutL1_ =
      std::conditional_t<transpose,
                         Catlass::detail::TagToLayout_t<T, LayoutL1T>,
                         Catlass::detail::TagToLayout_t<T, LayoutL1>>;

# Strategy 1: atomic_add kernel


@tilelang.jit(pass_configs=_pass_configs)
def atomic_add_kernel(N, D, num_segments, block_D, rows_per_core, dtype="float"):
    d_blocks = (D + block_D - 1) // block_D
    num_blocks = (N + rows_per_core - 1) // rows_per_core
    rows_per_vec = rows_per_core // VEC_NUM

    @T.prim_func
    def main(
        Data: T.Tensor((N, D), dtype),
        SegIds: T.Tensor((N,), "int32"),
        Output: T.Tensor((num_segments, D), dtype),
    ):
        with T.Kernel(num_blocks, is_npu=True) as (cid, vid):
            row_ub = T.alloc_ub([1, block_D], dtype)
            seg_ub = T.alloc_ub([1], "int32")

            for j in T.serial(rows_per_vec):
                row = cid * rows_per_core + j * VEC_NUM + vid
                if row < N:
                    T.copy(SegIds[row : row + 1], seg_ub)

                    for d_blk in T.serial(d_blocks):
                        T.copy(
                            Data[row : row + 1, d_blk * block_D : (d_blk + 1) * block_D],
                            row_ub,
                        )
                        T.tile.atomic_add(Output[seg_ub[0], d_blk * block_D], row_ub)

    return main


# Strategy 2: seg_reduce kernel (large D, small N)


@tilelang.jit(out_idx=[2], pass_configs=_pass_configs)
def seg_reduce_kernel(N, D, num_segments, block_D, max_seg_len, dtype="float"):
    d_blocks = (D + block_D - 1) // block_D

    @T.prim_func
    def main(
        SortedData: T.Tensor((N, D), dtype),
        Offsets: T.Tensor((num_segments + 1,), "int32"),
        Output: T.Tensor((num_segments, D), dtype),
    ):
        with T.Kernel(num_segments * d_blocks, is_npu=True) as (cid, vid):
            seg = cid // d_blocks
            d_blk = cid % d_blocks
            start = Offsets[seg]
            end = Offsets[seg + 1]

            acc_ub = T.alloc_ub([block_D], dtype)
            T.tile.fill(acc_ub, 0.0)
            row_ub = T.alloc_ub([block_D], dtype)

            for j in T.serial(max_seg_len):
                row = start + j
                if row < end:
                    T.copy(SortedData[row, d_blk * block_D], row_ub)
                    T.tile.add(acc_ub, acc_ub, row_ub)

            T.copy(acc_ub, Output[seg, d_blk * block_D])

    return main


# Strategy 3: block_reduce kernel (small D, large N, single segment)

